use vstd::prelude::*;

verus! {

/// Mathematical spec: compute the leftover amount after filling free space,
/// with negative results clamped to 0, and then clamped into the i8 range.
spec fn spec_solve(input: Seq<i8>) -> Seq<i8> {
    if input.len() < 3 {
        Seq::<i8>::empty()
    } else {
        let capacity: int = input[0] as int;
        let current: int  = input[1] as int;
        let incoming: int = input[2] as int;

        let free_space: int = capacity - current;
        let leftover_raw: int = incoming - free_space;
        let leftover0: int = if leftover_raw < 0 { 0 } else { leftover_raw };

        let clamped: int =
            if leftover0 < (i8::MIN as int) {
                i8::MIN as int
            } else if leftover0 > (i8::MAX as int) {
                i8::MAX as int
            } else {
                leftover0
            };

        Seq::<i8>::singleton(clamped as i8)
    }
}

fn solve(input: Vec<i8>) -> (out: Vec<i8>)
    ensures
        out@ == spec_solve(input@),
{
    if input.len() < 3 {
        return Vec::new();
    }

    let capacity = input[0] as i16;
    let current = input[1] as i16;
    let incoming = input[2] as i16;

    let free_space = capacity - current;
    let mut leftover = incoming - free_space;
    if leftover < 0 {
        leftover = 0;
    }

    // Clamp to i8 range before returning
    let clamped = leftover.clamp(i8::MIN as i16, i8::MAX as i16) as i8;
    vec![clamped]
}

} // verus!

